out.push("\n\n### 10.3 JavaScript 核心实现\n\n```javascript\nconst input = document.querySelector('#search-input');\n\nconst listbox = document.querySelector('#search-results');\n\nlet activeIndex = -1;\n\nfunction setActiveOption(index) {\n  const options = [\n    ...listbox.querySelectorAll('[role=\"option\"]')\n  ];\n\n  if (index < 0 || index >= options.length) {\n    activeIndex = -1;\n\n    input.removeAttribute('aria-activedescendant');\n\n    options.forEach(option => {\n      option.classList.remove('is-active');\n    });\n\n    return;\n  }\n\n  activeIndex = index;\n\n  options.forEach((option, i) => {\n    option.classList.toggle(\n      'is-active',\n      i === index\n    );\n  });\n\n  const option = options[index];\n\n  input.setAttribute(\n    'aria-activedescendant',\n    option.id\n  );\n\n  option.scrollIntoView({\n    block: 'nearest',\n    behavior: 'instant'\n  });\n}\n```\n\n这里没有执行：\n\n```javascript\noption.focus();\n```\n\n只是更新了活动项的 ID、视觉样式和滚动位置。\n\n这意味着 input 仍然可以接收键盘输入。\n\n方向键处理：\n\n```javascript\ninput.addEventListener('keydown', event => {\n  if (event.isComposing) return;\n\n  if (input.getAttribute('aria-expanded') !== 'true') {\n    return;\n  }\n\n  const options = [\n    ...listbox.querySelectorAll('[role=\"option\"]')\n  ];\n\n  if (!options.length) return;\n\n  switch (event.key) {\n    case 'ArrowDown':\n      event.preventDefault();\n\n      setActiveOption(\n        (activeIndex + 1) % options.length\n      );\n\n      break;\n\n    case 'ArrowUp':\n      event.preventDefault();\n\n      setActiveOption(\n        activeIndex <= 0\n          ? options.length - 1\n          : activeIndex - 1\n      );\n\n      break;\n\n    case 'Enter':\n      if (activeIndex >= 0) {\n        event.preventDefault();\n\n        selectOption(options[activeIndex]);\n      }\n\n      break;\n\n    case 'Escape':\n      event.preventDefault();\n\n      closeSearchResults();\n\n      break;\n  }\n});\n```\n\n其中 `selectOption()` 和 `closeSearchResults()` 属于业务层函数。\n\n关闭搜索结果时，还需要清理活动项：\n\n```javascript\nfunction closeSearchResults() {\n  setActiveOption(-1);\n\n  input.setAttribute('aria-expanded', 'false');\n\n  listbox.hidden = true;\n}\n```\n\n对于 AJAX 搜索建议，每次重新渲染列表之前，也应该检查或清理 `aria-activedescendant`，避免它指向已经不存在的 DOM 元素。\n\n以上只是虚拟焦点的核心代码，并不是完整的 Combobox 实现。选中状态、输入值更新、异步请求竞争、打开逻辑等问题将在第 16 课深入讲解。\n\n---\n\n## 11. Roving Tabindex 与 aria-activedescendant 对比\n\n");
